    INSERT INTO questions (module_id, lesson_id, topic_tag, question_type, question_en, options_en, correct_answer, explanation_en, difficulty, is_mock_test_eligible)
    VALUES
    (4,1,'defensive-driving','multiple_choice','What is the two-second rule?','["Wait 2 seconds before starting","Keep at least 2 seconds following distance","Check mirrors every 2 seconds","Honk every 2 seconds"]',1,'Keep at least 2 seconds of following distance behind the vehicle ahead.',1,true),
    (4,1,'defensive-driving','multiple_choice','In wet conditions, following distance should be at least:','["2 seconds","4 seconds","1 second","10 seconds"]',1,'Double to 4 seconds in wet conditions. Stopping distance increases.',1,true),
    (4,1,'defensive-driving','multiple_choice','In foggy conditions, you should:','["Use high beam","Use dipped headlights and fog lights","Use hazard lights","Use no lights"]',1,'Use dipped headlights and fog lights. High beam reflects off fog.',1,true),
    (4,1,'defensive-driving','multiple_choice','What is the safe following distance at 100 km/h?','["30 metres","55-60 metres","100 metres","10 metres"]',1,'At 100 km/h, safe following distance is about 55-60 metres (2+ seconds).',2,true),
    (4,1,'defensive-driving','multiple_choice','What should you do if the vehicle behind is tailgating you?','["Speed up","Increase your following distance from the car ahead","Brake suddenly","Ignore them"]',1,'Increase your following distance from the car ahead to give yourself more reaction time.',2,true),
    (4,1,'defensive-driving','multiple_choice','What is the purpose of a blind spot check?','["To check for traffic you cannot see in mirrors","To check your blindfold","To check the sun","To check behind your head"]',0,'Blind spot checks find vehicles not visible in mirrors. Always check before changing lanes.',1,true),
    (4,1,'defensive-driving','multiple_choice','When should you check your blind spots?','["Only on the highway","Before changing lanes, turning, or merging","Never","Only at night"]',1,'Check blind spots before any lane change, turn, or merge.',1,true),
    (4,1,'defensive-driving','multiple_choice','What is the most common cause of rear-end collisions?','["Speeding","Following too closely","Bad weather","Tyre blowout"]',1,'Following too closely (tailgating) is the most common cause of rear-end collisions.',1,true),
    (4,1,'defensive-driving','multiple_choice','What should you do at a blind corner?','["Speed up","Slow down and honk if necessary","Stop completely","Drive normally"]',1,'Slow down at blind corners. Sound horn if visibility is very poor.',2,true),
    (4,1,'defensive-driving','multiple_choice','What is defensive driving?','["Driving slowly","Anticipating hazards and being prepared","Driving aggressively","Driving without rules"]',1,'Defensive driving means anticipating hazards and being prepared to react safely.',1,true),
    (4,1,'defensive-driving','multiple_choice','What should you do when approaching a pedestrian crossing?','["Speed up","Slow down and be prepared to stop","Honk","Drive normally"]',1,'Slow down and be prepared to stop. Pedestrians may step out unexpectedly.',1,true),
    (4,1,'defensive-driving','multiple_choice','What is the safest way to approach an intersection?','["Speed up to clear it","Slow down, check both ways, proceed when safe","Honk and go","Follow the car ahead closely"]',1,'Slow down, check both directions, and proceed only when it is safe.',1,true),
    (4,1,'defensive-driving','multiple_choice','What should you do if you feel drowsy while driving?','["Open a window","Pull over safely and rest","Drink coffee and continue","Turn up the radio"]',1,'Pull over safely and rest. Drowsy driving is as dangerous as drunk driving.',1,true),
    (4,1,'defensive-driving','multiple_choice','What is the effect of fatigue on driving?','["No effect","Slower reaction times and poor judgement","Better focus","Improved reflexes"]',1,'Fatigue slows reaction times and impairs judgement. Take breaks every 2 hours.',2,true),
    (4,1,'defensive-driving','multiple_choice','What should you do before a long journey?','["Just start driving","Check vehicle, plan route, rest beforehand","Drink energy drinks","Drive at night to avoid traffic"]',1,'Check your vehicle, plan your route, and rest before a long journey.',1,true),
    (4,1,'defensive-driving','multiple_choice','What is the danger of driving in another vehicle blind spot?','["None","The other driver cannot see you","Better fuel economy","Improved visibility"]',1,'Driving in another vehicle blind spot is dangerous. They may change lanes into you.',2,true),
    (4,1,'defensive-driving','multiple_choice','What should you do when a large truck is behind you?','["Speed up","Allow extra space and avoid sudden braking","Ignore it","Brake suddenly"]',1,'Allow extra space. Trucks need longer to stop. Avoid sudden braking.',2,true),
    (4,1,'defensive-driving','multiple_choice','When passing a large truck, you should:','["Linger alongside","Pass quickly and do not cut in too soon","Drive slowly past","Honk repeatedly"]',1,'Pass quickly and do not cut back in until you can see the truck in your mirror.',2,true),
    (4,1,'defensive-driving','multiple_choice','What is the safest speed in a residential area with children playing?','["50 km/h","30 km/h or slower","40 km/h","20 km/h only near schools"]',1,'30 km/h or slower in residential areas. Children may dart into the road.',1,true),
    (4,1,'defensive-driving','multiple_choice','What should you do if an oncoming vehicle drifts into your lane?','["Speed up","Steer right, honk, and flash lights","Stop in your lane","Move left"]',1,'Steer to the left (off the road if needed), honk and flash lights to alert the driver.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is hazard perception?','["Seeing hazards only","Anticipating and identifying potential hazards early","Reacting to hazards after they happen","Avoiding all roads"]',1,'Hazard perception is the ability to anticipate and identify potential hazards early.',1,true),
    (4,2,'defensive-driving','multiple_choice','What is a common hazard at Nigerian roundabouts?','["Nothing","Vehicles not giving way and motorcycles weaving","Traffic lights","Pedestrians only"]',1,'Vehicles failing to give way and motorcycles weaving through traffic are common hazards.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a common hazard at Nigerian markets?','["Nothing","Pedestrians, traders, and parked vehicles on the road","Traffic lights","Speed cameras"]',1,'Markets have pedestrians, traders, and parked vehicles spilling onto the road. Slow down.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when approaching a parked bus?','["Speed up past it","Slow down — pedestrians may emerge","Honk loudly","Ignore it"]',1,'Slow down. Pedestrians may step out from behind the bus without looking.',1,true),
    (4,2,'defensive-driving','multiple_choice','What is a common hazard at night in Nigeria?','["Nothing","Unlit vehicles, potholes, and animals on the road","Traffic lights","Speed cameras"]',1,'Unlit vehicles, potholes, and animals on the road are common night hazards.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when you see children near the road?','["Speed up","Slow down and be prepared to stop","Honk","Drive normally"]',1,'Slow down and be prepared to stop. Children are unpredictable.',1,true),
    (4,2,'defensive-driving','multiple_choice','What is a common hazard at junctions?','["Nothing","Vehicles running red lights or not giving way","Traffic lights","Speed bumps"]',1,'Vehicles running red lights or failing to give way are common junction hazards.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when approaching a construction zone?','["Speed up","Slow down, watch for workers and equipment","Honk","Drive normally"]',1,'Slow down and watch for workers, equipment, and changed road conditions.',1,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard of driving in heavy rain?','["Nothing","Reduced visibility and aquaplaning risk","Better grip","Clearer view"]',1,'Heavy rain reduces visibility and creates aquaplaning risk. Reduce speed.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is aquaplaning?','["Driving on water","Tyres lose contact with road due to water layer","A type of boat","Normal wet driving"]',1,'Aquaplaning is when tyres lose contact with the road on a layer of water. Ease off throttle.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do if your vehicle aquaplanes?','["Brake hard","Ease off the accelerator, steer straight, do not brake","Turn sharply","Accelerate"]',1,'Ease off the accelerator, keep steering straight, do not brake hard.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a common hazard with okadas (motorcycles)?','["Nothing","They weave through traffic and appear unexpectedly","They follow all rules","They are slow"]',1,'Okadas weave through traffic and can appear unexpectedly. Always check blind spots.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when an okada is weaving through traffic near you?','["Speed up","Maintain position, do not make sudden moves","Move toward them","Brake suddenly"]',1,'Maintain your position and do not make sudden moves. Let them pass safely.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard of driving near trailers?','["Nothing","Wide turns and blind spots on both sides","They are slow only","They are always safe"]',1,'Trailers have large blind spots and make wide turns. Give them space.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when a trailer is turning?','["Stay back and give room","Pass quickly on the inside","Honk","Drive normally"]',0,'Stay back and give the trailer room to turn. Do not pass on the inside.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard at railway crossings?','["Nothing","Trains cannot stop quickly","Traffic lights","Speed bumps"]',1,'Trains cannot stop quickly. Always check both ways and never cross if a train is approaching.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do at an uncontrolled railway crossing?','["Speed across","Stop, look, listen, and cross when clear","Honk and go","Follow the car ahead"]',1,'Stop, look both ways, listen for trains, and cross only when completely clear.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard of driving on a narrow bridge?','["Nothing","Oncoming traffic and limited space","Speed cameras","Traffic lights"]',1,'Narrow bridges have limited space. Slow down and give way to oncoming traffic if needed.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when approaching a narrow bridge?','["Speed up","Slow down and assess if you have right of way","Honk","Drive normally"]',1,'Slow down and assess. Give way to larger vehicles or oncoming traffic if the bridge is single track.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard of driving in harmattan season?','["Nothing","Poor visibility from dust haze","Better visibility","Clear roads"]',1,'Harmattan dust haze reduces visibility significantly. Use lights and reduce speed.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do in harmattan haze?','["Use high beam","Use dipped headlights, reduce speed, increase following distance","Drive normally","Use no lights"]',1,'Use dipped headlights, reduce speed, and increase following distance.',2,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard of driving during the rainy season?','["Nothing","Flooding, reduced visibility, slippery roads","Better roads","Clear visibility"]',1,'Rainy season brings flooding, reduced visibility, and slippery roads. Drive cautiously.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do if you encounter a flooded road?','["Drive through fast","Turn back — do not drive through floodwater","Drive through slowly","Follow other vehicles"]',1,'Do not drive through floodwater. Turn back and find an alternative route.',2,true),
    (4,2,'defensive-driving','multiple_choice','How deep does water need to be to float a car?','["1 metre","30 cm for small cars, 60 cm for SUVs","2 metres","3 metres"]',1,'As little as 30 cm of water can float a small car. 60 cm can float an SUV.',3,true),
    (4,2,'defensive-driving','multiple_choice','What is a hazard of potholes?','["Nothing","Tyre damage, loss of control, and accidents","Better driving","Clear roads"]',1,'Potholes can damage tyres, cause loss of control, and lead to accidents. Avoid if safe.',2,true),
    (4,2,'defensive-driving','multiple_choice','What should you do when you see a pothole?','["Hit it at speed","Slow down and steer around if safe","Ignore it","Brake hard"]',1,'Slow down and steer around if it is safe to do so. Check mirrors before swerving.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the most important rule for night driving?','["Drive faster to get home","Reduce speed and use headlights properly","Use high beam always","Follow closely"]',1,'Reduce speed and use headlights properly. Visibility is reduced at night.',1,true),
    (4,3,'defensive-driving','multiple_choice','When should you use high beam headlights?','["In built-up areas","On unlit roads with no oncoming traffic","In traffic","Always at night"]',1,'Use high beam on unlit roads with no oncoming traffic. Dip for other vehicles.',1,true),
    (4,3,'defensive-driving','multiple_choice','When must you dip your headlights?','["Never","When meeting oncoming traffic or following another vehicle","Only in town","Only in rain"]',1,'Dip headlights when meeting oncoming traffic or following another vehicle closely.',1,true),
    (4,3,'defensive-driving','multiple_choice','What is the danger of high beam in fog?','["Better visibility","Light reflects back, reducing visibility","No effect","Improves safety"]',1,'High beam reflects off fog particles back at you. Use dipped lights and fog lights.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if blinded by oncoming headlights?','["Look at the oncoming lights","Look to the left edge of the road","Close your eyes","Speed up"]',1,'Look to the left edge of the road to avoid being blinded by oncoming headlights.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of fog lights?','["To look cool","To see better in fog by cutting under it","To replace headlights","For decoration"]',1,'Fog lights are mounted low and cut under the fog to improve visibility.',2,true),
    (4,3,'defensive-driving','multiple_choice','When should you use hazard lights?','["When parking","Only in an emergency or to warn of a hazard ahead","In traffic","At night"]',1,'Use hazard lights only in emergencies or to warn other drivers of a hazard ahead.',1,true),
    (4,3,'defensive-driving','multiple_choice','What is the danger of driving at dawn or dusk?','["Nothing","Reduced visibility and animals on the road","Better visibility","Clearer roads"]',1,'Dawn and dusk have reduced visibility. Animals are more active at these times.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when driving at dawn or dusk?','["Drive normally","Reduce speed and watch for animals and pedestrians","Speed up","Use high beam always"]',1,'Reduce speed and watch for animals and pedestrians. Visibility is poor.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of reflective triangles?','["Decoration","To warn other drivers if you break down","To park","To measure distance"]',1,'Reflective triangles warn other drivers of your stopped vehicle. Place at least 45m behind.',2,true),
    (4,3,'defensive-driving','multiple_choice','How many reflective triangles should you carry?','["One","Two","Three","None"]',1,'Carry at least two reflective triangles. Place one 45m behind and one 45m ahead.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if your vehicle breaks down at night?','["Stay in the car","Turn on hazard lights, place triangles, move away from traffic","Walk for help immediately","Flag down vehicles"]',1,'Turn on hazard lights, place reflective triangles, and move to a safe location away from traffic.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest following distance at night?','["2 seconds","4-5 seconds","1 second","Same as day"]',1,'Increase following distance to 4-5 seconds at night. Reduced visibility means more reaction time needed.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of a headlight range adjustment?','["Nothing","To avoid dazzling oncoming drivers when loaded","For decoration","To see further"]',1,'Adjust headlight range when the vehicle is heavily loaded so you do not dazzle oncoming drivers.',3,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if your headlights fail at night?','["Keep driving","Slow down, use hazard lights, stop safely","Use interior lights","Drive faster"]',1,'Slow down, use hazard lights, and stop safely. Do not continue without headlights.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the danger of driving with only parking lights?','["None","Insufficient visibility — other drivers cannot see you well","Better fuel economy","Safer"]',1,'Parking lights are not bright enough for driving. Use dipped headlights.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when approaching a tunnel?','["Speed up","Turn on dipped headlights, remove sunglasses","Keep sunglasses on","Use high beam"]',1,'Turn on dipped headlights before entering a tunnel. Remove sunglasses.',1,true),
    (4,3,'defensive-driving','multiple_choice','What is the danger of driving too closely at night?','["None","Reduced reaction time and blinded by brake lights","Better visibility","Safer"]',1,'Following too closely at night gives less reaction time. Brake lights can dazzle you.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if you miss your turn at night?','["Reverse","Continue to the next junction and turn around","Stop and reverse","Make a U-turn immediately"]',1,'Never reverse or stop. Continue to the next junction and find a safe place to turn.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of cats eyes (road studs)?','["Decoration","To mark lanes and road edges at night","To slow traffic","To guide pedestrians"]',1,'Cats eyes reflect headlights to mark lanes and road edges, improving night visibility.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when dazzled by headlights behind you?','["Nothing","Adjust your interior mirror to night setting","Speed up","Brake suddenly"]',1,'Flip your interior mirror to the night (anti-dazzle) setting.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest speed on an unlit rural road at night?','["Normal speed","Reduced speed — within headlight range","High speed","Any speed"]',1,'Reduce speed so you can stop within the distance lit by your headlights.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of driving lights?','["Decoration","Additional lighting for rural driving at night","To replace headlights","For fog only"]',1,'Driving lights provide additional long-range lighting for rural roads at night.',3,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when an oncoming vehicle does not dip its lights?','["Flash your high beam repeatedly","Look to the left edge, slow down, do not retaliate","Speed up","Close your eyes"]',1,'Look to the left edge of the road, slow down. Do not retaliate with your high beam.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of cornering lights?','["Decoration","To illuminate the inside of a corner at night","To replace headlights","For parking"]',1,'Cornering lights illuminate the inside of a bend when turning at night.',3,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when driving in a convoy at night?','["Use high beam","Keep headlights on dipped, maintain safe distance","Use hazard lights","Drive close together"]',1,'Keep headlights on dipped beam and maintain safe following distance.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the danger of tinted windows at night?','["None","Further reduces already poor visibility","Better visibility","Safer"]',1,'Tinted windows further reduce night visibility. Extra caution needed.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do before overtaking at night?','["Just go","Ensure you can see clearly, the road is straight, and no oncoming lights","Use high beam only","Honk first"]',1,'Ensure clear visibility, straight road, and no oncoming headlights before overtaking at night.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest action when an animal runs onto the road at night?','["Swerve to avoid","Brake firmly in a straight line","Speed up","Honk and continue"]',1,'Brake firmly in a straight line. Do not swerve — you may lose control.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when approaching a village at night?','["Speed up","Slow down — people and animals may be on the road","Drive normally","Use high beam"]',1,'Slow down. People, animals, and unlit obstacles are common in villages at night.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of reflective clothing for pedestrians?','["Fashion","To be visible to drivers at night","To stay warm","For safety regulations only"]',1,'Reflective clothing makes pedestrians visible to drivers at night. Watch for them.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if you see a pedestrian in dark clothing at night?','["Speed up","Slow down and give them space","Honk","Drive normally"]',1,'Slow down. Dark-clothed pedestrians are hard to see at night. Give them space.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest way to park at night?','["Anywhere","In a well-lit area, off the road","On the road","In a tunnel"]',1,'Park in a well-lit area, off the road. Use parking lights or hazard lights if necessary.',1,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when leaving a parked position at night?','["Just pull out","Check mirrors, blind spots, signal, then move","Honk and go","Use high beam"]',1,'Check mirrors, blind spots, signal, then move out carefully.',1,true),
    (4,3,'defensive-driving','multiple_choice','What is the danger of driving with one headlight?','["None","Reduced visibility and confusing other drivers","Better fuel economy","Safer"]',1,'Driving with one headlight reduces visibility and confuses oncoming drivers. Replace immediately.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if your brake lights fail?','["Keep driving","Use hand signals, get them fixed immediately","Use hazard lights only","Drive at night only"]',1,'Use hand signals to indicate braking. Get brake lights fixed immediately.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of a third brake light?','["Decoration","Additional visibility for following drivers","Extra lighting","For reversing"]',1,'The high-mounted third brake light improves visibility for drivers behind you.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when driving in a dust storm?','["Speed up","Pull over, turn off lights, wait","Use high beam","Drive normally"]',1,'Pull over, turn off lights (so others do not follow your lights into you), and wait.',3,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest action when visibility drops below 50 metres?','["Continue at reduced speed","Pull over and stop safely","Use high beam","Follow tail lights"]',1,'Pull over and stop safely. Do not continue driving in near-zero visibility.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when approaching a hill crest at night?','["Speed up","Slow down — you cannot see what is over the hill","Use high beam","Drive normally"]',1,'Slow down. You cannot see oncoming traffic or obstacles over the crest.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of road studs on motorway lanes?','["Decoration","To mark lanes clearly at night and in poor weather","To slow traffic","For noise"]',1,'Road studs reflect headlights to clearly mark lanes at night and in poor weather.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if you feel sleepy but cannot stop?','["Open window, drink water, take deep breaths","Speed up to arrive sooner","Turn up music","Drive faster"]',0,'Open window, drink water, take deep breaths. Find a safe place to stop as soon as possible.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the most important safety rule for driving?','["Speed","Always wear your seatbelt","Use indicators","Have a clean car"]',1,'Always wear your seatbelt. It is the single most effective safety device in your vehicle.',1,true),
    (4,3,'defensive-driving','multiple_choice','What should you do before starting a journey?','["Just drive","Check mirrors, seat, seatbelt, and fuel","Drink coffee","Call someone"]',1,'Check mirrors, adjust seat, fasten seatbelt, and check fuel level before starting.',1,true),
    (4,3,'defensive-driving','multiple_choice','What is the purpose of the MSM routine?','["Military routine","Mirror-Signal-Manoeuvre before any action","Morning Safety Check","Motorway Safety Method"]',1,'MSM = Mirror, Signal, Manoeuvre. Always use this routine before any change in direction or speed.',1,true),
    (4,3,'defensive-driving','multiple_choice','What should you do when approaching a green light that has been green for a while?','["Speed up","Be prepared for it to change to amber","Ignore it","Honk"]',1,'Be prepared. A long green light may change to amber as you approach. Do not speed up.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest way to handle a tyre blowout?','["Brake hard","Grip steering firmly, ease off accelerator, do not brake","Steer sharply","Accelerate"]',1,'Grip the steering firmly, ease off the accelerator, do not brake hard. Pull over safely.',2,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if your accelerator sticks?','["Brake hard","Shift to neutral, brake gently, steer to safety","Turn off engine while moving","Pull handbrake"]',1,'Shift to neutral, brake gently, and steer to a safe stop. Turn off engine when stopped.',3,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if your brakes fail?','["Panic","Pump brakes, use handbrake gradually, steer to safety","Turn off engine","Pull steering hard"]',1,'Pump the brake pedal, use handbrake gradually, steer to a safe area. Use engine braking.',3,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if your steering fails?','["Brake hard","Slow down gradually, use hazard lights, stop safely","Turn off engine","Pull handbrake"]',1,'Slow down gradually, turn on hazard lights, and stop safely. Steering failure is extremely dangerous.',3,true),
    (4,3,'defensive-driving','multiple_choice','What should you do if you skid?','["Brake hard","Steer into the skid, ease off accelerator","Steer away","Accelerate"]',1,'Steer into the skid (in the direction the rear is sliding) and ease off the accelerator. Do not brake.',2,true),
    (4,3,'defensive-driving','multiple_choice','What is the safest way to drive in strong winds?','["Speed up","Grip steering firmly, reduce speed, watch for gusts","Drive normally","Use high beam"]',1,'Grip steering firmly, reduce speed, and be prepared for sudden gusts, especially on open roads.',2,true);
